#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

static inline std::vector<int64_t> infer_output_shape_transpose3d_stride1_pad0(const at::Tensor& x, const at::Tensor& w) {
    // x: [N, Cin, D, H, W], w: [Cin, Cout, K, K, K]
    auto N   = x.size(0);
    auto Cin = x.size(1);
    auto D   = x.size(2);
    auto H   = x.size(3);
    auto W   = x.size(4);

    TORCH_CHECK(w.dim() == 5, "weight must be 5D");
    TORCH_CHECK(w.size(0) == Cin, "weight Cin mismatch");
    TORCH_CHECK(w.size(2) == w.size(3) && w.size(3) == w.size(4), "kernel must be cubic");
    auto Cout = w.size(1);
    auto K    = w.size(2);

    auto Do = D + K - 1;
    auto Ho = H + K - 1;
    auto Wo = W + K - 1;
    return {N, Cout, Do, Ho, Wo};
}

at::Tensor conv_transposed_3d_square_input_square_kernel_custom_impl_npu(const at::Tensor& x, const at::Tensor& weight) {
    auto out_sizes = infer_output_shape_transpose3d_stride1_pad0(x, weight);
    at::Tensor result = at::empty(out_sizes, x.options());
    EXEC_NPU_CMD(aclnnConvTransposed3dSquareInputSquareKernelCustom, x, weight, result);
    return result;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
    m.impl("conv_transposed_3d_square_input_square_kernel_custom", &conv_transposed_3d_square_input_square_kernel_custom_impl_npu);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv_transposed_3d_square_input_square_kernel_custom", &conv_transposed_3d_square_input_square_kernel_custom_impl_npu, "ConvTranspose3d KxKxK (stride=1, pad=0)");
}
